/* Interactive overview actions and local demonstration controls. */
let inboxMode='pending';state.allergies??={};
function uiIcon(name){const paths={patients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',shield:'M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11 M12 8v5 M12 17h.01',heart:'M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78',lab:'M9 3h6 M10 3v7l-6 9a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2l-6-9V3 M8 15h8',link:'M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2',arrow:'M5 12h14 M13 6l6 6-6 6',close:'M6 6l12 12 M6 18L18 6'};return `<svg class="uiicon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`}
function metricCard(icon,label,value,sub,target,tone){const selectedCard=view==='Overview'&&target===filter;return `<button class="metriccard ${tone} ${selectedCard?'chosen':''}" onclick="openMetric('${target}')" aria-label="${label}: ${value}. ${sub}" ${target!=='results'?`aria-pressed="${selectedCard}"`:''}><span class="metrichead"><span class="metricicon">${uiIcon(icon)}</span><span class="metricarrow">${uiIcon('arrow')}</span></span><span class="metriclabel">${label}</span><strong class="metricvalue">${value}</strong><span class="metricfoot">${sub}</span></button>`}
function openMetric(target){if(target==='results'){inboxMode='all';go('Integration');return}filter=target;search='';page=0;go('Overview');document.querySelector('.tools input')?.focus({preventScroll:true})}
function setInbox(mode){inboxMode=mode;render()}
function openDialog(title,body){document.querySelector('#workflowDialog')?.remove();const d=document.createElement('dialog');d.id='workflowDialog';d.innerHTML=`<div class="dialoghead"><h2 id="dialogTitle">${title}</h2><button class="iconbutton" aria-label="Close dialog" onclick="closeDialog()">${uiIcon('close')}</button></div>${body}`;d.setAttribute('aria-labelledby','dialogTitle');document.body.append(d);d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('close',()=>d.remove());d.showModal()}
function closeDialog(){document.querySelector('#workflowDialog')?.close()}
function openConnection(){openDialog('Integration workspace',`<span class="pill amber">Simulation mode</span><p style="margin-top:16px">No hospital LIS or EHR endpoint is connected. You can test patient-matched results, report corrections and local review tracking.</p><div class="connectionsteps"><div><b>1</b><span>Download the synthetic result template</span></div><div><b>2</b><span>Import JSON or run a patient demo feed</span></div><div><b>3</b><span>Review results and audit the action</span></div></div><div class="actions"><button class="btn primary" onclick="closeDialog();inboxMode='all';go('Integration')">Open result inbox →</button><button class="btn" onclick="download('fn-result-example.json',exampleResults())">Download template</button></div><details><summary>What is needed for live integration?</summary><p>An authorized test endpoint, message schema, patient/encounter matching, authentication, institutional alert limits and clinical validation. No credentials are requested or stored in this demo.</p></details>`)}
function allergyLabel(pid){const a=state.allergies[pid];return a? a.status==='none'?'Allergy: none reported (demo)':a.status==='known'?'Allergy recorded (demo)':'Allergy: unknown — verify':'Allergy: unknown — verify'}
function openAllergy(){if(!selected)return;const a=state.allergies[id(selected)]||{status:'unknown',substance:'',reaction:''};openDialog('Allergy review · '+esc(id(selected)),`<p>Local synthetic-case documentation only. This does not approve medication selection or change the source workbook.</p><form onsubmit="event.preventDefault();saveAllergy(this)"><label class="field">Status<select name="status" onchange="toggleAllergyFields(this.value)"><option value="unknown" ${a.status==='unknown'?'selected':''}>Unknown / not yet verified</option><option value="none" ${a.status==='none'?'selected':''}>No known allergies reported</option><option value="known" ${a.status==='known'?'selected':''}>Allergy reported</option></select></label><div id="allergyFields" ${a.status!=='known'?'hidden':''}><label class="field">Substance<input name="substance" maxlength="120" value="${esc(a.substance)}" ${a.status==='known'?'required':''}></label><label class="field">Reaction / severity<input name="reaction" maxlength="200" value="${esc(a.reaction)}" ${a.status==='known'?'required':''}></label></div><div class="actions"><button class="btn primary" type="submit">Save demo review</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`)}
function toggleAllergyFields(status){const box=document.querySelector('#allergyFields');box.hidden=status!=='known';box.querySelectorAll('input').forEach(i=>i.required=status==='known')}
function saveAllergy(form){const data=new FormData(form),status=data.get('status'),substance=String(data.get('substance')||'').trim(),reaction=String(data.get('reaction')||'').trim();if(status==='known'&&(!substance||!reaction))return;state.allergies[id(selected)]={status,substance:status==='known'?substance:'',reaction:status==='known'?reaction:'',reviewedAt:new Date().toISOString()};closeDialog();save('Allergy review saved ('+status+') — synthetic demo',id(selected))}
// Keep review actions idempotent and associated with their result's patient.
reviewResult=function(eid){if(state.labReviews[eid])return;const r=state.results.find(r=>r.eventId===eid);if(!r)return;state.labReviews[eid]=new Date().toISOString();save('Simulated result review documented: '+eid,r.patientId)};
function openDemoPatient(){openPatient(id(patients[0]));changeTab('Laboratory')}
